const retryStatusChangeStatuses = new Set(["failed", "broken", "passed"]);
export const StatusByPriority = ["failed", "broken", "passed", "skipped", "unknown"];
export const statusToPriority = (status) => {
    if (!status) {
        return -1;
    }
    return StatusByPriority.indexOf(status);
};
export const getWorstStatus = (items) => {
    if (items.length === 0) {
        return;
    }
    return items.sort((a, b) => statusToPriority(a) - statusToPriority(b))[0];
};
export const hasRetriesStatusChange = (current, retries) => retryStatusChangeStatuses.has(current.status) &&
    retries.some(({ status }) => retryStatusChangeStatuses.has(status) && status !== current.status);
